class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        int j = 0;
        long long cnt = 0;
        for (int i = 0; i < n1; i++) {
            for (char c : s1) {
                if (c == s2[j]) {
                    if (++j == (int)s2.size()) { cnt++; j = 0; }
                }
            }
        }
        return cnt / n2;
    }
};

