            return 0
        idxr, cntr = {}, [0]
        j = 0
        for i in range(1, n1 + 1):
            for c in s1:
                if c == s2[j]:
                    j += 1
                    if j == len(s2):
                        j = 0
                        cntr.append(cntr[-1] + 1)
            cntr.append(cntr[-1])
            if j in idxr:
                p = idxr[j]
                plen = i - p
                pcnt = cntr[i] - cntr[p]
                rem = (n1 - p) % plen
                total = cntr[p] + pcnt * ((n1 - p) // plen)
                total += cntr[p + rem] - cntr[p]
                return total // n2
            idxr[j] = i
        return cntr[n1] // n2

