class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        unordered_map<int,int> idxr;
        vector<int> cnt{0};
        int j = 0;
        for (int i = 1; i <= n1; i++) {
            for (char c : s1) {
                if (c == s2[j]) {
                    if (++j == (int)s2.size()) { j = 0; cnt.push_back(cnt.back() + 1); }
                }
            }
            cnt.push_back(cnt.back());
            auto it = idxr.find(j);
            if (it != idxr.end()) {
                int p = it->second;
                int plen = i - p;
                long long pcnt = cnt[i] - cnt[p];
                long long q = (long long)(n1 - p) / plen;
                int rem = (n1 - p) % plen;
                long long total = cnt[p] + pcnt * q + (cnt[p + rem] - cnt[p]);
                return total / n2;
            }
            idxr[j] = i;
        }
        return cnt[n1] / n2;
    }
};

