class Solution {
    public int getMaxRepetitions(String s1, int n1, String s2, int n2) {
        Map<Integer,Integer> idxr = new HashMap<>();
        List<Integer> cnt = new ArrayList<>();
        cnt.add(0);
        int j = 0;
        for (int i = 1; i <= n1; i++) {
            for (char c : s1.toCharArray()) {
                if (c == s2.charAt(j)) {
                    if (++j == s2.length()) { j = 0; cnt.add(cnt.get(cnt.size()-1) + 1); }
                }
            }
            cnt.add(cnt.get(cnt.size()-1));
            Integer p = idxr.get(j);
            if (p != null) {
                int plen = i - p;
                long pcnt = cnt.get(i) - cnt.get(p);
                long q = (n1 - p) / plen;
                int rem = (n1 - p) % plen;
                long total = cnt.get(p) + pcnt * q + (cnt.get(p + rem) - cnt.get(p));
                return (int)(total / n2);
            }
            idxr.put(j, i);
        }
        return cnt.get(n1) / n2;
    }
}

