    const idxr = new Map();
    const cnt = [0];
    let j = 0;
    for (let i = 1; i <= n1; i++) {
        for (const c of s1) {
            if (c === s2[j]) {
                if (++j === s2.length) { j = 0; cnt.push(cnt[cnt.length-1] + 1); }
            }
