        cnt.push(cnt[cnt.length-1]);
        if (idxr.has(j)) {
            const p = idxr.get(j);
            const plen = i - p;
            const pcnt = cnt[i] - cnt[p];
            const q = Math.floor((n1 - p) / plen);
            const rem = (n1 - p) % plen;
            const total = cnt[p] + pcnt * q + (cnt[p + rem] - cnt[p]);
            return Math.floor(total / n2);
        }
        idxr.set(j, i);
    }
    return Math.floor(cnt[n1] / n2);
};
